import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p49_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_softmax_sigmoid_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_softmax_sigmoid", &fused_softmax_sigmoid_cuda, "Fused softmax+sigmoid over channel dim for 5D CUDA tensor");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// One block per (n, d, h, w) spatial position.
// Threads cooperate across the channel dimension to compute:
//   numerically stable softmax, then sigmoid of each result.
__global__ void fused_softmax_sigmoid_kernel(
    const float* __restrict__ input,
    float*       __restrict__ output,
    int C,
    int spatial_size  // N*D*H*W
) {
    // blockIdx.x indexes the flattened (n, d, h, w) position
    int pos = blockIdx.x;
    if (pos >= spatial_size) return;

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // Pointer to this position's channel slice
    // Layout: (N, C, D, H, W) -> stride for channel dim = spatial_size
    // input[n*C*DHW + c*DHW + dhw] = input[c * spatial_size + pos]
    // We need to sum across c, so base = pos and stride = spatial_size
    const float* in_ptr = input + pos;  // in_ptr[c * spatial_size] = input at channel c
    float*       out_ptr = output + pos;

    // Step 1: find max over channels (for numerical stability)
    float thread_max = -1e38f;
    for (int c = tid; c < C; c += block_size) {
        float val = in_ptr[c * spatial_size];
        thread_max = fmaxf(thread_max, val);
    }

    // Warp-level max reduction
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1)
        thread_max = fmaxf(thread_max, __shfl_down_sync(mask, thread_max, offset));

    // Block-level max reduction via shared memory
    extern __shared__ float smem[];
    int warp_id = tid / 32;
    int lane_id = tid % 32;
    int num_warps = (block_size + 31) / 32;

    if (lane_id == 0) smem[warp_id] = thread_max;
    __syncthreads();

    float block_max;
    if (tid < num_warps) {
        block_max = smem[tid];
        for (int offset = 16; offset > 0; offset >>= 1)
            block_max = fmaxf(block_max, __shfl_down_sync(mask, block_max, offset));
        if (tid == 0) smem[0] = block_max;
    }
    __syncthreads();
    block_max = smem[0];

    // Step 2: compute exp(x - max) and sum
    float thread_sum = 0.0f;
    for (int c = tid; c < C; c += block_size) {
        float val = expf(in_ptr[c * spatial_size] - block_max);
        smem[num_warps + c] = val;  // store exp values
        thread_sum += val;
    }
    __syncthreads();

    // Warp-level sum reduction
    for (int offset = 16; offset > 0; offset >>= 1)
        thread_sum += __shfl_down_sync(mask, thread_sum, offset);

    if (lane_id == 0) smem[warp_id] = thread_sum;
    __syncthreads();

    float block_sum;
    if (tid < num_warps) {
        block_sum = smem[tid];
        for (int offset = 16; offset > 0; offset >>= 1)
            block_sum += __shfl_down_sync(mask, block_sum, offset);
        if (tid == 0) smem[0] = block_sum;
    }
    __syncthreads();
    block_sum = smem[0];

    // Step 3: normalize (softmax) and apply sigmoid, write output
    float inv_sum = 1.0f / block_sum;
    for (int c = tid; c < C; c += block_size) {
        float softmax_val = smem[num_warps + c] * inv_sum;
        float sigmoid_val = 1.0f / (1.0f + expf(-softmax_val));
        out_ptr[c * spatial_size] = sigmoid_val;
    }
}

torch::Tensor fused_softmax_sigmoid_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "Input must be float32");
    TORCH_CHECK(x.dim() == 5, "Input must be 5D (N,C,D,H,W)");

    x = x.contiguous();

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);
    int spatial_size = N * D * H * W;

    auto output = torch::empty_like(x);

    // Choose block size: 128 threads is a good balance for channel reductions
    int block_size = 128;
    // Shared memory: num_warps floats for reductions + C floats for exp values
    int num_warps = (block_size + 31) / 32;
    size_t smem_bytes = (num_warps + C) * sizeof(float);

    fused_softmax_sigmoid_kernel<<<spatial_size, block_size, smem_bytes>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        C,
        spatial_size
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a 3D transposed convolution, applies Softmax and Sigmoid.
        """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias=True):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, bias=bias)
        self.softmax = nn.Softmax(dim=1)
        self.sigmoid = nn.Sigmoid()
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, D, H, W).

                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, out_channels, D, H, W).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.conv_transpose(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if x.is_cuda and x.dtype == torch.float32 and x.dim() == 5:
            x = _stark_get_extension().fused_softmax_sigmoid(x)
        else:
            x = torch.sigmoid(torch.softmax(x, dim=1))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # sigmoid already applied in fused_softmax_sigmoid above (or in the fallback)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
        # <<<END_IMPROVE>>>

