CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// One block per (n, d, h, w) voxel. Threads cooperate across C channels.
// Block size is min(next_pow2(C), 1024). Shared memory holds per-thread max and sum.
__global__ void fused_softmax_sigmoid_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int D, int H, int W
) {
    // Each block handles one spatial voxel
    int voxel = blockIdx.x;  // index over N*D*H*W
    int DHW = D * H * W;
    int n = voxel / DHW;
    int rem = voxel % DHW;
    int d = rem / (H * W);
    int rem2 = rem % (H * W);
    int h = rem2 / W;
    int w = rem2 % W;

    // Base pointer for this voxel's channel slice: input[n, :, d, h, w]
    // NCDHW layout: stride over C is D*H*W, stride over N is C*D*H*W
    int base_offset = ((n * C) * D + d) * H * W + h * W + w;  // = n*C*D*H*W + 0*D*H*W + d*H*W + h*W + w
    // Actually: input[n,c,d,h,w] = input[n*C*DHW + c*DHW + d*H*W + h*W + w]
    int voxel_stride = DHW;  // stride to go from channel c to c+1
    // Fix base_offset: n*C*DHW + d*H*W + h*W + w
    base_offset = n * C * DHW + d * H * W + h * W + w;

    int tid = threadIdx.x;
    int block_size = blockDim.x;

    // --- Pass 1: find max across channels ---
    float local_max = -FLT_MAX;
    for (int c = tid; c < C; c += block_size) {
        float val = input[base_offset + c * voxel_stride];
        local_max = fmaxf(local_max, val);
    }

    // Block-wide max reduction via shared memory
    extern __shared__ float smem[];
    float* smax = smem;
    float* ssum = smem + block_size;

    smax[tid] = local_max;
    __syncthreads();
    for (int stride = block_size >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            smax[tid] = fmaxf(smax[tid], smax[tid + stride]);
        }
        __syncthreads();
    }
    float block_max = smax[0];
    __syncthreads();

    // --- Pass 2: compute sum of exp(x - max) ---
    float local_sum = 0.0f;
    for (int c = tid; c < C; c += block_size) {
        float val = input[base_offset + c * voxel_stride];
        local_sum += __expf(val - block_max);
    }

    ssum[tid] = local_sum;
    __syncthreads();
    for (int stride = block_size >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            ssum[tid] += ssum[tid + stride];
        }
        __syncthreads();
    }
    float block_sum = ssum[0];
    __syncthreads();

    // --- Pass 3: write softmax * sigmoid ---
    float inv_sum = 1.0f / block_sum;
    for (int c = tid; c < C; c += block_size) {
        float val = input[base_offset + c * voxel_stride];
        float sm = __expf(val - block_max) * inv_sum;
        // sigmoid(sm)
        float sig = 1.0f / (1.0f + __expf(-sm));
        output[base_offset + c * voxel_stride] = sig;
    }
}

torch::Tensor fused_softmax_sigmoid_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 5, "Input must be 5D (N,C,D,H,W)");

    if (!x.is_contiguous()) {
        x = x.contiguous();
    }
    if (x.scalar_type() != at::kFloat) {
        return at::sigmoid(at::softmax(x, 1));
    }

    int N = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    auto output = torch::empty_like(x);

    int num_voxels = N * D * H * W;

    // Choose block size: next power of 2 >= C, capped at 1024
    int block_size = 1;
    while (block_size < C) block_size <<= 1;
    if (block_size > 1024) block_size = 1024;
    if (block_size < 32) block_size = 32;

    // shared memory: 2 * block_size floats (max buffer + sum buffer)
    int smem_bytes = 2 * block_size * sizeof(float);

    fused_softmax_sigmoid_kernel<<<num_voxels, block_size, smem_bytes>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, D, H, W
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a 3D transposed convolution, applies Softmax and Sigmoid.
        """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias=True):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, output_padding=output_padding, bias=bias)
        self.softmax = nn.Softmax(dim=1)
        self.sigmoid = nn.Sigmoid()
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, in_channels, D, H, W).

                Returns:
                    torch.Tensor: Output tensor of shape (batch_size, out_channels, D, H, W).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.conv_transpose(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if x.is_cuda and x.dtype == torch.float32 and x.dim() == 5:
            x = _stark_get_extension().fused_softmax_sigmoid(x.contiguous())
        else:
            x = torch.sigmoid(torch.softmax(x, dim=1))
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # sigmoid already fused into fused_softmax_sigmoid above (or fallback path)
        # <<<END_IMPROVE>>>
